<!DOCTYPE html>
<html lang="hu">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <meta name="apple-mobile-web-app-capable" content="yes">
    <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
    <title>AI Kutatóágens</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            -webkit-tap-highlight-color: transparent;
        }

        :root {
            --glass-bg: rgba(255, 255, 255, 0.08);
            --glass-border: rgba(255, 255, 255, 0.18);
            --glass-shadow: rgba(0, 0, 0, 0.1);
            --tint-primary: rgba(0, 122, 255, 0.8);
            --tint-success: rgba(52, 199, 89, 0.8);
            --tint-warning: rgba(255, 149, 0, 0.8);
            --tint-danger: rgba(255, 59, 48, 0.8);
            --text-primary: rgba(255, 255, 255, 0.95);
            --text-secondary: rgba(255, 255, 255, 0.65);
            --text-tertiary: rgba(255, 255, 255, 0.45);
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: var(--text-primary);
            overflow: hidden;
            height: 100vh;
            width: 100vw;
        }

        .glass {
            background: var(--glass-bg);
            backdrop-filter: blur(20px) saturate(180%);
            -webkit-backdrop-filter: blur(20px) saturate(180%);
            border: 1px solid var(--glass-border);
            box-shadow: 0 8px 32px var(--glass-shadow);
        }

        #app {
            display: flex;
            flex-direction: column;
            height: 100vh;
            width: 100vw;
            position: relative;
        }

        #header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 12px 16px;
            border-bottom: 1px solid var(--glass-border);
        }

        #hamburger-btn {
            width: 44px;
            height: 44px;
            border: none;
            background: none;
            cursor: pointer;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            gap: 5px;
            padding: 10px;
        }

        #hamburger-btn span {
            display: block;
            width: 24px;
            height: 2px;
            background: var(--text-primary);
            transition: all 0.3s ease;
        }

        #title {
            font-size: 18px;
            font-weight: 600;
            flex: 1;
            text-align: center;
        }

        #menu-btn {
            width: 44px;
            height: 44px;
            border: none;
            background: none;
            cursor: pointer;
            font-size: 24px;
            color: var(--text-primary);
            display: flex;
            align-items: center;
            justify-content: center;
        }

        #sidebar {
            position: fixed;
            top: 0;
            left: -320px;
            width: 320px;
            height: 100vh;
            transition: left 0.3s ease;
            z-index: 1000;
            display: flex;
            flex-direction: column;
        }

        #sidebar.open {
            left: 0;
        }

        #sidebar-header {
            padding: 16px;
            border-bottom: 1px solid var(--glass-border);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        #sidebar-header h2 {
            font-size: 20px;
            font-weight: 600;
        }

        #close-sidebar-btn {
            width: 36px;
            height: 36px;
            border: none;
            background: none;
            cursor: pointer;
            font-size: 24px;
            color: var(--text-primary);
        }

        #conversations-list {
            flex: 1;
            overflow-y: auto;
            padding: 8px;
        }

        .conversation-item {
            padding: 12px;
            margin-bottom: 8px;
            border-radius: 12px;
            cursor: pointer;
            transition: background 0.2s ease;
            border: 1px solid transparent;
        }

        .conversation-item:hover {
            background: rgba(255, 255, 255, 0.1);
            border-color: var(--glass-border);
        }

        .conversation-item.active {
            background: var(--tint-primary);
            border-color: rgba(255, 255, 255, 0.3);
        }

        .conversation-title {
            font-weight: 500;
            margin-bottom: 4px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .conversation-meta {
            font-size: 12px;
            color: var(--text-tertiary);
        }

        #new-chat-btn {
            margin: 12px 16px;
            padding: 12px;
            border: none;
            border-radius: 12px;
            background: var(--tint-primary);
            color: white;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        #new-chat-btn:active {
            transform: scale(0.95);
        }

        #overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            background: rgba(0, 0, 0, 0.5);
            z-index: 999;
            opacity: 0;
            pointer-events: none;
            transition: opacity 0.3s ease;
        }

        #overlay.visible {
            opacity: 1;
            pointer-events: auto;
        }

        #chat-container {
            flex: 1;
            overflow-y: auto;
            padding: 16px;
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        .message {
            display: flex;
            gap: 12px;
            max-width: 85%;
            animation: fadeIn 0.3s ease;
        }

        @keyframes fadeIn {
            from {
                opacity: 0;
                transform: translateY(10px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .message.user {
            align-self: flex-end;
            flex-direction: row-reverse;
        }

        .message.assistant {
            align-self: flex-start;
        }

        .message-avatar {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 600;
            flex-shrink: 0;
        }

        .message.user .message-avatar {
            background: var(--tint-primary);
        }

        .message.assistant .message-avatar {
            background: var(--tint-success);
        }

        .message-content {
            padding: 12px 16px;
            border-radius: 18px;
            word-wrap: break-word;
            position: relative;
        }

        .message.user .message-content {
            background: var(--tint-primary);
        }

        .message.assistant .message-content {
            background: var(--glass-bg);
            border: 1px solid var(--glass-border);
        }

        .message-actions {
            display: flex;
            gap: 8px;
            margin-top: 8px;
            opacity: 0;
            transition: opacity 0.2s ease;
        }

        .message:hover .message-actions {
            opacity: 1;
        }

        .message-action-btn {
            padding: 4px 8px;
            font-size: 12px;
            border: none;
            border-radius: 6px;
            background: rgba(255, 255, 255, 0.1);
            color: var(--text-secondary);
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .message-action-btn:hover {
            background: rgba(255, 255, 255, 0.2);
            color: var(--text-primary);
        }

        #input-container {
            padding: 12px 16px;
            border-top: 1px solid var(--glass-border);
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        #mode-selector {
            display: flex;
            gap: 8px;
            justify-content: center;
        }

        .mode-btn {
            flex: 1;
            padding: 10px;
            border: 1px solid var(--glass-border);
            border-radius: 12px;
            background: var(--glass-bg);
            color: var(--text-secondary);
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s ease;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 4px;
        }

        .mode-btn.active {
            background: var(--tint-primary);
            color: white;
            border-color: rgba(255, 255, 255, 0.3);
        }

        .mode-btn-icon {
            font-size: 20px;
        }

        #input-row {
            display: flex;
            gap: 8px;
            align-items: flex-end;
        }

        #attachment-btn {
            width: 44px;
            height: 44px;
            border: none;
            border-radius: 12px;
            background: var(--glass-bg);
            border: 1px solid var(--glass-border);
            cursor: pointer;
            font-size: 20px;
            color: var(--text-primary);
            flex-shrink: 0;
            transition: all 0.2s ease;
        }

        #attachment-btn:active {
            transform: scale(0.95);
        }

        #input-wrapper {
            flex: 1;
            display: flex;
            flex-direction: column;
            border-radius: 12px;
            background: var(--glass-bg);
            border: 1px solid var(--glass-border);
            overflow: hidden;
        }

        #message-input {
            flex: 1;
            border: none;
            background: none;
            color: var(--text-primary);
            font-size: 15px;
            padding: 12px 16px;
            outline: none;
            resize: none;
            font-family: inherit;
            max-height: 120px;
        }

        #message-input::placeholder {
            color: var(--text-tertiary);
        }

        #send-btn {
            width: 44px;
            height: 44px;
            border: none;
            border-radius: 12px;
            background: var(--tint-primary);
            cursor: pointer;
            font-size: 20px;
            color: white;
            flex-shrink: 0;
            transition: all 0.2s ease;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        #send-btn:active {
            transform: scale(0.95);
        }

        #send-btn:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        .typing-indicator {
            display: flex;
            gap: 4px;
            padding: 12px 16px;
        }

        .typing-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--text-secondary);
            animation: typing 1.4s infinite;
        }

        .typing-dot:nth-child(2) {
            animation-delay: 0.2s;
        }

        .typing-dot:nth-child(3) {
            animation-delay: 0.4s;
        }

        @keyframes typing {
            0%, 60%, 100% {
                transform: translateY(0);
            }
            30% {
                transform: translateY(-10px);
            }
        }

        #dropdown-menu {
            position: fixed;
            top: 60px;
            right: 16px;
            border-radius: 12px;
            padding: 8px;
            min-width: 200px;
            z-index: 1001;
            opacity: 0;
            pointer-events: none;
            transform: translateY(-10px);
            transition: all 0.2s ease;
        }

        #dropdown-menu.visible {
            opacity: 1;
            pointer-events: auto;
            transform: translateY(0);
        }

        .dropdown-item {
            padding: 12px 16px;
            border-radius: 8px;
            cursor: pointer;
            transition: background 0.2s ease;
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .dropdown-item:hover {
            background: rgba(255, 255, 255, 0.1);
        }

        .dropdown-icon {
            font-size: 18px;
        }

        #bottom-sheet {
            position: fixed;
            bottom: -100%;
            left: 0;
            width: 100vw;
            max-height: 70vh;
            border-radius: 20px 20px 0 0;
            transition: bottom 0.3s ease;
            z-index: 1002;
            display: flex;
            flex-direction: column;
        }

        #bottom-sheet.visible {
            bottom: 0;
        }

        #bottom-sheet-handle {
            width: 36px;
            height: 4px;
            border-radius: 2px;
            background: var(--text-tertiary);
            margin: 12px auto 8px;
        }

        #bottom-sheet-header {
            padding: 8px 16px 16px;
            border-bottom: 1px solid var(--glass-border);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        #bottom-sheet-header h3 {
            font-size: 18px;
            font-weight: 600;
        }

        #bottom-sheet-search {
            width: 100%;
            padding: 10px 16px;
            margin: 12px 0;
            border: 1px solid var(--glass-border);
            border-radius: 10px;
            background: rgba(255, 255, 255, 0.05);
            color: var(--text-primary);
            font-size: 15px;
            outline: none;
        }

        #bottom-sheet-search::placeholder {
            color: var(--text-tertiary);
        }

        #bottom-sheet-content {
            flex: 1;
            overflow-y: auto;
            padding: 8px 16px;
        }

        .history-item {
            padding: 12px;
            margin-bottom: 8px;
            border-radius: 12px;
            cursor: pointer;
            border: 1px solid var(--glass-border);
            transition: all 0.2s ease;
        }

        .history-item:hover {
            background: rgba(255, 255, 255, 0.1);
            transform: translateX(4px);
        }

        .history-item-title {
            font-weight: 500;
            margin-bottom: 4px;
        }

        .history-item-meta {
            font-size: 12px;
            color: var(--text-tertiary);
        }

        #file-upload-menu {
            position: fixed;
            bottom: -100%;
            left: 0;
            width: 100vw;
            border-radius: 20px 20px 0 0;
            transition: bottom 0.3s ease;
            z-index: 1002;
            padding: 20px;
        }

        #file-upload-menu.visible {
            bottom: 0;
        }

        .upload-option {
            padding: 16px;
            margin-bottom: 12px;
            border-radius: 12px;
            cursor: pointer;
            border: 1px solid var(--glass-border);
            display: flex;
            align-items: center;
            gap: 16px;
            transition: all 0.2s ease;
        }

        .upload-option:hover {
            background: rgba(255, 255, 255, 0.1);
        }

        .upload-option-icon {
            width: 44px;
            height: 44px;
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 20px;
        }

        .upload-option-text {
            flex: 1;
        }

        .upload-option-title {
            font-weight: 500;
            margin-bottom: 4px;
        }

        .upload-option-desc {
            font-size: 13px;
            color: var(--text-secondary);
        }

        #cancel-upload-btn {
            width: 100%;
            padding: 16px;
            border: none;
            border-radius: 12px;
            background: var(--glass-bg);
            border: 1px solid var(--glass-border);
            color: var(--text-primary);
            font-weight: 600;
            cursor: pointer;
            margin-top: 8px;
        }

        .progress-bar {
            width: 100%;
            height: 3px;
            background: rgba(255, 255, 255, 0.1);
            border-radius: 2px;
            margin-top: 8px;
            overflow: hidden;
        }

        .progress-fill {
            height: 100%;
            background: var(--tint-primary);
            transition: width 0.3s ease;
        }

        .status-badge {
            display: inline-block;
            padding: 4px 10px;
            border-radius: 12px;
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            margin-left: 8px;
        }

        .status-badge.running {
            background: var(--tint-warning);
            color: white;
        }

        .status-badge.completed {
            background: var(--tint-success);
            color: white;
        }

        .status-badge.failed {
            background: var(--tint-danger);
            color: white;
        }

        .empty-state {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100%;
            color: var(--text-secondary);
            text-align: center;
            padding: 32px;
        }

        .empty-state-icon {
            font-size: 64px;
            margin-bottom: 16px;
            opacity: 0.5;
        }

        .empty-state-title {
            font-size: 20px;
            font-weight: 600;
            margin-bottom: 8px;
        }

        .empty-state-desc {
            font-size: 14px;
            color: var(--text-tertiary);
        }

        .stop-generating-btn {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 8px 16px;
            border: none;
            border-radius: 12px;
            background: var(--tint-danger);
            color: white;
            cursor: pointer;
            font-weight: 500;
            margin: 8px auto;
            transition: all 0.2s ease;
        }

        .stop-generating-btn:active {
            transform: scale(0.95);
        }

        input[type="file"] {
            display: none;
        }

        @media (min-width: 768px) {
            #app {
                max-width: 800px;
                margin: 0 auto;
                border-left: 1px solid var(--glass-border);
                border-right: 1px solid var(--glass-border);
            }
        }

        ::-webkit-scrollbar {
            width: 8px;
        }

        ::-webkit-scrollbar-track {
            background: transparent;
        }

        ::-webkit-scrollbar-thumb {
            background: rgba(255, 255, 255, 0.2);
            border-radius: 4px;
        }

        ::-webkit-scrollbar-thumb:hover {
            background: rgba(255, 255, 255, 0.3);
        }
    </style>
</head>
<body>
    <div id="app" class="glass">
        <div id="header" class="glass">
            <button id="hamburger-btn">
                <span></span>
                <span></span>
                <span></span>
            </button>
            <div id="title">AI Kutatóágens</div>
            <button id="menu-btn">⋮</button>
        </div>

        <div id="sidebar" class="glass">
            <div id="sidebar-header">
                <h2>Előzmények</h2>
                <button id="close-sidebar-btn">✕</button>
            </div>
            <div id="conversations-list"></div>
            <button id="new-chat-btn">+ Új beszélgetés</button>
        </div>

        <div id="overlay"></div>

        <div id="chat-container"></div>

        <div id="input-container">
            <div id="mode-selector">
                <button class="mode-btn active" data-mode="chat">
                    <span class="mode-btn-icon">💬</span>
                    <span>Chat</span>
                </button>
                <button class="mode-btn" data-mode="search">
                    <span class="mode-btn-icon">🔍</span>
                    <span>Keresés</span>
                </button>
                <button class="mode-btn" data-mode="research">
                    <span class="mode-btn-icon">🔬</span>
                    <span>Kutatás</span>
                </button>
            </div>
            <div id="input-row">
                <button id="attachment-btn">+</button>
                <div id="input-wrapper">
                    <textarea id="message-input" placeholder="Írj egy üzenetet..." rows="1"></textarea>
                </div>
                <button id="send-btn">➤</button>
            </div>
        </div>

        <div id="dropdown-menu" class="glass">
            <div class="dropdown-item" data-action="history">
                <span class="dropdown-icon">📜</span>
                <span>Előzmények</span>
            </div>
            <div class="dropdown-item" data-action="settings">
                <span class="dropdown-icon">⚙️</span>
                <span>Beállítások</span>
            </div>
        </div>

        <div id="bottom-sheet" class="glass">
            <div id="bottom-sheet-handle"></div>
            <div id="bottom-sheet-header">
                <h3>Előzmények</h3>
                <button id="close-bottom-sheet-btn" style="background: none; border: none; font-size: 24px; color: var(--text-primary); cursor: pointer;">✕</button>
            </div>
            <div style="padding: 0 16px;">
                <input type="text" id="bottom-sheet-search" placeholder="Keresés az előzményekben...">
            </div>
            <div id="bottom-sheet-content"></div>
        </div>

        <div id="file-upload-menu" class="glass">
            <div class="upload-option" data-action="camera">
                <div class="upload-option-icon" style="background: var(--tint-primary);">📷</div>
                <div class="upload-option-text">
                    <div class="upload-option-title">Fotó készítése</div>
                    <div class="upload-option-desc">Készíts fotót a kamerával</div>
                </div>
            </div>
            <div class="upload-option" data-action="gallery">
                <div class="upload-option-icon" style="background: var(--tint-success);">🖼️</div>
                <div class="upload-option-text">
                    <div class="upload-option-title">Válassz a galériából</div>
                    <div class="upload-option-desc">Képek és videók</div>
                </div>
            </div>
            <div class="upload-option" data-action="files">
                <div class="upload-option-icon" style="background: var(--tint-warning);">📁</div>
                <div class="upload-option-text">
                    <div class="upload-option-title">Fájlok böngészése</div>
                    <div class="upload-option-desc">Dokumentumok és egyéb fájlok</div>
                </div>
            </div>
            <button id="cancel-upload-btn">Mégse</button>
        </div>

        <input type="file" id="file-input-camera" accept="image/*" capture="environment">
        <input type="file" id="file-input-gallery" accept="image/*,video/*" multiple>
        <input type="file" id="file-input-files" multiple>
    </div>

    <script>
        const API_BASE = window.location.origin;
        let currentConversationId = null;
        let currentMode = 'chat';
        let currentJobId = null;
        let isGenerating = false;
        let conversations = [];
        let ws = null;

        const elements = {
            hamburgerBtn: document.getElementById('hamburger-btn'),
            sidebar: document.getElementById('sidebar'),
            overlay: document.getElementById('overlay'),
            closeSidebarBtn: document.getElementById('close-sidebar-btn'),
            newChatBtn: document.getElementById('new-chat-btn'),
            conversationsList: document.getElementById('conversations-list'),
            chatContainer: document.getElementById('chat-container'),
            messageInput: document.getElementById('message-input'),
            sendBtn: document.getElementById('send-btn'),
            attachmentBtn: document.getElementById('attachment-btn'),
            menuBtn: document.getElementById('menu-btn'),
            dropdownMenu: document.getElementById('dropdown-menu'),
            bottomSheet: document.getElementById('bottom-sheet'),
            bottomSheetContent: document.getElementById('bottom-sheet-content'),
            bottomSheetSearch: document.getElementById('bottom-sheet-search'),
            closeBottomSheetBtn: document.getElementById('close-bottom-sheet-btn'),
            fileUploadMenu: document.getElementById('file-upload-menu'),
            cancelUploadBtn: document.getElementById('cancel-upload-btn'),
            modeButtons: document.querySelectorAll('.mode-btn')
        };

        elements.hamburgerBtn.addEventListener('click', () => {
            elements.sidebar.classList.add('open');
            elements.overlay.classList.add('visible');
        });

        elements.closeSidebarBtn.addEventListener('click', closeSidebar);
        elements.overlay.addEventListener('click', () => {
            closeSidebar();
            closeDropdown();
            closeBottomSheet();
            closeFileUploadMenu();
        });

        function closeSidebar() {
            elements.sidebar.classList.remove('open');
            elements.overlay.classList.remove('visible');
        }

        elements.newChatBtn.addEventListener('click', () => {
            currentConversationId = null;
            elements.chatContainer.innerHTML = '';
            showEmptyState();
            closeSidebar();
        });

        elements.menuBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            elements.dropdownMenu.classList.toggle('visible');
        });

        function closeDropdown() {
            elements.dropdownMenu.classList.remove('visible');
        }

        document.querySelectorAll('.dropdown-item').forEach(item => {
            item.addEventListener('click', (e) => {
                const action = e.currentTarget.dataset.action;
                if (action === 'history') {
                    loadHistoryBottomSheet();
                } else if (action === 'settings') {
                    alert('Beállítások funkcionalitás hamarosan');
                }
                closeDropdown();
            });
        });

        elements.closeBottomSheetBtn.addEventListener('click', closeBottomSheet);

        function closeBottomSheet() {
            elements.bottomSheet.classList.remove('visible');
            elements.overlay.classList.remove('visible');
        }

        elements.bottomSheetSearch.addEventListener('input', (e) => {
            filterHistoryItems(e.target.value);
        });

        elements.attachmentBtn.addEventListener('click', () => {
            elements.fileUploadMenu.classList.add('visible');
            elements.overlay.classList.add('visible');
        });

        elements.cancelUploadBtn.addEventListener('click', closeFileUploadMenu);

        function closeFileUploadMenu() {
            elements.fileUploadMenu.classList.remove('visible');
            elements.overlay.classList.remove('visible');
        }

        document.querySelectorAll('.upload-option').forEach(option => {
            option.addEventListener('click', (e) => {
                const action = e.currentTarget.dataset.action;
                if (action === 'camera') {
                    document.getElementById('file-input-camera').click();
                } else if (action === 'gallery') {
                    document.getElementById('file-input-gallery').click();
                } else if (action === 'files') {
                    document.getElementById('file-input-files').click();
                }
                closeFileUploadMenu();
            });
        });

        document.getElementById('file-input-camera').addEventListener('change', handleFileUpload);
        document.getElementById('file-input-gallery').addEventListener('change', handleFileUpload);
        document.getElementById('file-input-files').addEventListener('change', handleFileUpload);

        async function handleFileUpload(e) {
            const files = e.target.files;
            if (!files.length) return;

            for (let file of files) {
                const formData = new FormData();
                formData.append('file', file);

                try {
                    const response = await fetch(`${API_BASE}/upload`, {
                        method: 'POST',
                        body: formData
                    });

                    if (response.ok) {
                        const result = await response.json();
                        addSystemMessage(`Fájl feltöltve: ${result.filename}`);
                    } else {
                        addSystemMessage(`Hiba a fájl feltöltésekor: ${file.name}`);
                    }
                } catch (error) {
                    console.error('Upload error:', error);
                    addSystemMessage(`Hiba: ${error.message}`);
                }
            }

            e.target.value = '';
        }

        elements.modeButtons.forEach(btn => {
            btn.addEventListener('click', () => {
                elements.modeButtons.forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                currentMode = btn.dataset.mode;
            });
        });

        elements.sendBtn.addEventListener('click', sendMessage);
        elements.messageInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
            }
        });

        elements.messageInput.addEventListener('input', (e) => {
            e.target.style.height = 'auto';
            e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';

            elements.sendBtn.disabled = !e.target.value.trim();
        });

        async function sendMessage() {
            const message = elements.messageInput.value.trim();
            if (!message || isGenerating) return;

            addUserMessage(message);
            elements.messageInput.value = '';
            elements.messageInput.style.height = 'auto';
            elements.sendBtn.disabled = true;
            isGenerating = true;

            showTypingIndicator();

            try {
                const response = await fetch(`${API_BASE}/chat`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        conversation_id: currentConversationId,
                        message: message,
                        mode: currentMode
                    })
                });

                if (response.ok) {
                    const result = await response.json();
                    currentJobId = result.job_id;
                    currentConversationId = result.conversation_id;

                    if (currentMode === 'chat') {
                        pollJobStatus(result.job_id);
                    } else {
                        connectWebSocket(result.job_id);
                    }
                } else {
                    removeTypingIndicator();
                    addSystemMessage('Hiba történt az üzenet küldésekor');
                    isGenerating = false;
                }
            } catch (error) {
                console.error('Send error:', error);
                removeTypingIndicator();
                addSystemMessage('Hálózati hiba: ' + error.message);
                isGenerating = false;
            }
        }

        function addUserMessage(text) {
            const messageDiv = document.createElement('div');
            messageDiv.className = 'message user';
            messageDiv.innerHTML = `
                <div class="message-avatar">Te</div>
                <div class="message-content">${escapeHtml(text)}</div>
            `;
            elements.chatContainer.appendChild(messageDiv);
            scrollToBottom();
            removeEmptyState();
        }

        function addAssistantMessage(text, sources = []) {
            removeTypingIndicator();

            const messageDiv = document.createElement('div');
            messageDiv.className = 'message assistant';

            let sourcesHtml = '';
            if (sources.length > 0) {
                sourcesHtml = '<div class="message-sources" style="margin-top: 12px; font-size: 12px; opacity: 0.7;">';
                sources.forEach((src, i) => {
                    sourcesHtml += `<div>${i + 1}. <a href="${src.url}" target="_blank" style="color: inherit;">${src.title}</a></div>`;
                });
                sourcesHtml += '</div>';
            }

            messageDiv.innerHTML = `
                <div class="message-avatar">AI</div>
                <div class="message-content">
                    ${formatMessage(text)}
                    ${sourcesHtml}
                    <div class="message-actions">
                        <button class="message-action-btn" onclick="copyMessage(this)">Másolás</button>
                        <button class="message-action-btn" onclick="regenerateMessage(this)">Újragenerálás</button>
                    </div>
                </div>
            `;
            elements.chatContainer.appendChild(messageDiv);
            scrollToBottom();
            isGenerating = false;
        }

        function addSystemMessage(text) {
            const messageDiv = document.createElement('div');
            messageDiv.className = 'message assistant';
            messageDiv.innerHTML = `
                <div class="message-avatar">⚠️</div>
                <div class="message-content">${escapeHtml(text)}</div>
            `;
            elements.chatContainer.appendChild(messageDiv);
            scrollToBottom();
        }

        function showTypingIndicator() {
            const indicator = document.createElement('div');
            indicator.className = 'message assistant typing-indicator-wrapper';
            indicator.id = 'typing-indicator';
            indicator.innerHTML = `
                <div class="message-avatar">AI</div>
                <div class="message-content">
                    <div class="typing-indicator">
                        <div class="typing-dot"></div>
                        <div class="typing-dot"></div>
                        <div class="typing-dot"></div>
                    </div>
                </div>
            `;
            elements.chatContainer.appendChild(indicator);
            scrollToBottom();
        }

        function removeTypingIndicator() {
            const indicator = document.getElementById('typing-indicator');
            if (indicator) {
                indicator.remove();
            }
        }

        function showEmptyState() {
            elements.chatContainer.innerHTML = `
                <div class="empty-state">
                    <div class="empty-state-icon">💡</div>
                    <div class="empty-state-title">Üdvözöllek!</div>
                    <div class="empty-state-desc">Válassz egy módot és kezdj el chattelni, keresni vagy kutatni!</div>
                </div>
            `;
        }

        function removeEmptyState() {
            const emptyState = elements.chatContainer.querySelector('.empty-state');
            if (emptyState) {
                emptyState.remove();
            }
        }

        async function pollJobStatus(jobId) {
            const maxAttempts = 60;
            let attempts = 0;

            const poll = async () => {
                if (attempts >= maxAttempts) {
                    removeTypingIndicator();
                    addSystemMessage('Időtúllépés');
                    isGenerating = false;
                    return;
                }

                try {
                    const response = await fetch(`${API_BASE}/status/${jobId}`);
                    if (response.ok) {
                        const status = await response.json();

                        if (status.status === 'completed') {
                            const reportResponse = await fetch(`${API_BASE}/report/${jobId}`);
                            if (reportResponse.ok) {
                                const report = await reportResponse.json();
                                addAssistantMessage(report.report, []);
                            }
                            return;
                        } else if (status.status === 'failed') {
                            removeTypingIndicator();
                            addSystemMessage('Hiba: ' + (status.error || 'Ismeretlen hiba'));
                            isGenerating = false;
                            return;
                        }

                        attempts++;
                        setTimeout(poll, 1000);
                    }
                } catch (error) {
                    console.error('Poll error:', error);
                    removeTypingIndicator();
                    addSystemMessage('Hiba a státusz lekérdezésekor');
                    isGenerating = false;
                }
            };

            poll();
        }

        function connectWebSocket(jobId) {
            const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
            const wsUrl = `${protocol}//${window.location.host}/ws/${jobId}`;

            ws = new WebSocket(wsUrl);

            ws.onopen = () => {
                console.log('WebSocket connected');
            };

            ws.onmessage = (event) => {
                const data = JSON.parse(event.data);

                if (data.type === 'status_update') {
                    updateTypingIndicatorWithProgress(data);
                } else if (data.type === 'final_result') {
                    fetchAndDisplayReport(jobId);
                }
            };

            ws.onerror = (error) => {
                console.error('WebSocket error:', error);
                removeTypingIndicator();
                addSystemMessage('WebSocket hiba');
                isGenerating = false;
            };

            ws.onclose = () => {
                console.log('WebSocket closed');
                ws = null;
            };
        }

        function updateTypingIndicatorWithProgress(data) {
            let indicator = document.getElementById('typing-indicator');
            if (indicator) {
                const progressPercent = Math.round(data.progress * 100);
                indicator.querySelector('.message-content').innerHTML = `
                    <div style="padding: 12px 16px;">
                        <div style="margin-bottom: 8px;">${escapeHtml(data.current_step)}</div>
                        <div class="progress-bar">
                            <div class="progress-fill" style="width: ${progressPercent}%"></div>
                        </div>
                        <div style="font-size: 11px; margin-top: 6px; opacity: 0.7;">${progressPercent}% - ${data.sources_count} forrás</div>
                    </div>
                `;
                scrollToBottom();
            }
        }

        async function fetchAndDisplayReport(jobId) {
            try {
                const response = await fetch(`${API_BASE}/report/${jobId}`);
                if (response.ok) {
                    const data = await response.json();
                    addAssistantMessage(data.report, []);
                    await loadConversations();
                }
            } catch (error) {
                console.error('Report fetch error:', error);
                addSystemMessage('Hiba a jelentés lekérésekor');
            }
        }

        async function loadConversations() {
            try {
                const response = await fetch(`${API_BASE}/conversations`);
                if (response.ok) {
                    const data = await response.json();
                    conversations = data.conversations;
                    renderConversations();
                }
            } catch (error) {
                console.error('Load conversations error:', error);
            }
        }

        function renderConversations() {
            elements.conversationsList.innerHTML = '';

            if (conversations.length === 0) {
                elements.conversationsList.innerHTML = '<div style="padding: 16px; text-align: center; color: var(--text-tertiary);">Nincs előzmény</div>';
                return;
            }

            conversations.forEach(conv => {
                const item = document.createElement('div');
                item.className = 'conversation-item';
                if (conv.conversation_id === currentConversationId) {
                    item.classList.add('active');
                }
                item.innerHTML = `
                    <div class="conversation-title">${escapeHtml(conv.title)}</div>
                    <div class="conversation-meta">${conv.message_count} üzenet · ${formatDate(conv.updated_at)}</div>
                `;
                item.addEventListener('click', () => loadConversation(conv.conversation_id));

                item.addEventListener('contextmenu', (e) => {
                    e.preventDefault();
                    if (confirm('Törlöd ezt a beszélgetést?')) {
                        deleteConversation(conv.conversation_id);
                    }
                });

                elements.conversationsList.appendChild(item);
            });
        }

        async function loadConversation(conversationId) {
            try {
                const response = await fetch(`${API_BASE}/conversation/${conversationId}`);
                if (response.ok) {
                    const conversation = await response.json();
                    currentConversationId = conversationId;
                    elements.chatContainer.innerHTML = '';

                    conversation.messages.forEach(msg => {
                        if (msg.role === 'user') {
                            addUserMessage(msg.content);
                        } else if (msg.role === 'assistant') {
                            addAssistantMessage(msg.content, msg.sources || []);
                        }
                    });

                    closeSidebar();
                }
            } catch (error) {
                console.error('Load conversation error:', error);
            }
        }

        async function deleteConversation(conversationId) {
            try {
                const response = await fetch(`${API_BASE}/conversation/${conversationId}`, {
                    method: 'DELETE'
                });
                if (response.ok) {
                    await loadConversations();
                    if (conversationId === currentConversationId) {
                        currentConversationId = null;
                        elements.chatContainer.innerHTML = '';
                        showEmptyState();
                    }
                }
            } catch (error) {
                console.error('Delete conversation error:', error);
            }
        }

        async function loadHistoryBottomSheet() {
            await loadConversations();
            elements.bottomSheetContent.innerHTML = '';

            if (conversations.length === 0) {
                elements.bottomSheetContent.innerHTML = '<div style="padding: 32px; text-align: center; color: var(--text-tertiary);">Nincs előzmény</div>';
            } else {
                conversations.forEach(conv => {
                    const item = document.createElement('div');
                    item.className = 'history-item';
                    item.innerHTML = `
                        <div class="history-item-title">${escapeHtml(conv.title)}</div>
                        <div class="history-item-meta">${conv.message_count} üzenet · ${formatDate(conv.updated_at)}</div>
                    `;
                    item.addEventListener('click', () => {
                        loadConversation(conv.conversation_id);
                        closeBottomSheet();
                    });
                    elements.bottomSheetContent.appendChild(item);
                });
            }

            elements.bottomSheet.classList.add('visible');
            elements.overlay.classList.add('visible');
        }

        function filterHistoryItems(query) {
            const items = elements.bottomSheetContent.querySelectorAll('.history-item');
            items.forEach(item => {
                const text = item.textContent.toLowerCase();
                if (text.includes(query.toLowerCase())) {
                    item.style.display = 'block';
                } else {
                    item.style.display = 'none';
                }
            });
        }

        function copyMessage(btn) {
            const content = btn.closest('.message-content').childNodes[0].textContent;
            navigator.clipboard.writeText(content).then(() => {
                const originalText = btn.textContent;
                btn.textContent = 'Másolva!';
                setTimeout(() => {
                    btn.textContent = originalText;
                }, 2000);
            });
        }

        function regenerateMessage(btn) {
            alert('Újragenerálás funkcionalitás hamarosan');
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        function formatMessage(text) {
            let formatted = escapeHtml(text);
            formatted = formatted.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
            formatted = formatted.replace(/\*(.*?)\*/g, '<em>$1</em>');
            formatted = formatted.replace(/\n/g, '<br>');
            return formatted;
        }

        function formatDate(isoString) {
            const date = new Date(isoString);
            const now = new Date();
            const diffMs = now - date;
            const diffMins = Math.floor(diffMs / 60000);
            const diffHours = Math.floor(diffMs / 3600000);
            const diffDays = Math.floor(diffMs / 86400000);

            if (diffMins < 1) return 'Most';
            if (diffMins < 60) return `${diffMins} perce`;
            if (diffHours < 24) return `${diffHours} órája`;
            if (diffDays < 7) return `${diffDays} napja`;
            return date.toLocaleDateString('hu-HU');
        }

        function scrollToBottom() {
            elements.chatContainer.scrollTop = elements.chatContainer.scrollHeight;
        }

        showEmptyState();
        loadConversations();
    </script>
</body>
</html>


